<?php
declare(strict_types=1);
namespace App\Controllers;

use App\Database;
use App\Services\CmsHtmlSanitizer;

final class CmsPublicController
{
    public function faq():void
    {
        $result=\App\Models\PublicContentModel::faqs();$groups=[];foreach($result['rows'] as $faq)$groups[(string)$faq['category']][]=$faq;$brand=\site_setting('company_name','MultiForex');$structured=['@context'=>'https://schema.org','@type'=>'FAQPage','mainEntity'=>[]];foreach($result['rows'] as $faq)$structured['mainEntity'][]=['@type'=>'Question','name'=>(string)$faq['question'],'acceptedAnswer'=>['@type'=>'Answer','text'=>strip_tags((string)$faq['answer'])]];$json=json_encode($structured,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);\render('public/faq',['title'=>'Frequently Asked Questions · '.$brand,'metaDescription'=>'Answers about demo trading, accounts, markets, the platform, security and support.','canonicalUrl'=>\site_url('faq'),'openGraphTitle'=>'Frequently Asked Questions · '.$brand,'openGraphDescription'=>'Straightforward information about the MultiForex demo environment.','companyName'=>$brand,'publicPageAssets'=>true,'faqAssets'=>true,'faqGroups'=>$groups,'faqAvailable'=>$result['ok'],'structuredData'=>$json]);
    }
    public function listing(string $type):void
    {
        $pdo=Database::connection();$where="a.status='published' AND a.published_at<=CURRENT_TIMESTAMP";$params=[];
        if($type==='education'){$where.=" AND c.slug NOT IN ('market-news','platform-updates')";}elseif($type==='market-news'){$where.=" AND c.slug='market-news'";}elseif($type==='articles'){$where.=" AND c.slug<>'platform-updates'";}
        if($type==='articles'){$q=$pdo->prepare("SELECT a.title,a.slug,a.excerpt,a.published_at,a.seo_title,a.meta_description,c.name category_name FROM articles a JOIN article_categories c ON c.id=a.category_id WHERE {$where} ORDER BY a.published_at DESC,a.id DESC LIMIT 100");}else{$q=$pdo->prepare("SELECT a.title,a.slug,a.excerpt,a.published_at,a.seo_title,a.meta_description,c.name category_name FROM articles a JOIN article_categories c ON c.id=a.category_id WHERE {$where} ORDER BY a.published_at DESC,a.id DESC LIMIT 100");}$q->execute($params);$rows=$q->fetchAll();$brand=\site_setting('company_name','MultiForex');$title=match($type){'education'=>'Learning Centre','market-news'=>'Market News',default=>'Articles'};
        $defaultSeoTitle=\site_setting('default_seo_title','MultiForex | Demo Global Trading Platform');\render('public/cms-listing',['title'=>($title==='Articles'?$defaultSeoTitle:$title.' · '.$brand),'metaDescription'=>\site_setting('default_seo_description','Explore simulated markets and demo trading tools with virtual funds on MultiForex.'),'canonicalUrl'=>\site_url($type),'openGraphTitle'=>$title.' · '.$brand,'openGraphDescription'=>\site_setting('default_seo_description','Explore simulated markets and demo trading tools with virtual funds on MultiForex.'),'companyName'=>$brand,'publicPageAssets'=>true,'cmsTitle'=>$title,'rows'=>$rows,'noindex'=>\auth_check()]);
    }
    public function article(string $slug):void
    {
        $pdo=Database::connection();$q=$pdo->prepare("SELECT a.*,c.name category_name FROM articles a JOIN article_categories c ON c.id=a.category_id WHERE a.slug=? AND a.status='published' AND a.published_at<=CURRENT_TIMESTAMP LIMIT 1");$q->execute([$slug]);$row=$q->fetch();if(!$row){$this->redirect('article',$slug);return;}$brand=\site_setting('company_name','MultiForex');$desc=$row['meta_description']?:$row['excerpt']?:\site_setting('default_seo_description','Explore simulated markets and demo trading tools with virtual funds on MultiForex');$content=CmsHtmlSanitizer::clean((string)$row['content']);
        \render('public/cms-article',['title'=>($row['seo_title']?:$row['title']).' · '.$brand,'metaDescription'=>$desc,'canonicalUrl'=>\site_url('article/'.$slug),'openGraphTitle'=>$row['seo_title']?:$row['title'],'openGraphDescription'=>$desc,'companyName'=>$brand,'publicPageAssets'=>true,'article'=>$row,'safeContent'=>$content,'noindex'=>\auth_check()]);
    }
    public function page(string $slug):void
    {
        if(in_array($slug,['about','security','terms','privacy','risk-disclosure'],true)){http_response_code(404);\render('public/not-found',['title'=>'Page not found']);return;}$q=Database::connection()->prepare("SELECT * FROM pages WHERE slug=? AND status='published' AND published_at<=CURRENT_TIMESTAMP LIMIT 1");$q->execute([$slug]);$row=$q->fetch();if(!$row){$this->redirect('page',$slug);return;}$brand=\site_setting('company_name','MultiForex');$desc=$row['meta_description']?:\site_setting('default_seo_description','Explore simulated markets and demo trading tools with virtual funds on MultiForex');$safe=CmsHtmlSanitizer::clean((string)$row['content']);\render('public/cms-page',['title'=>($row['seo_title']?:\site_setting('default_seo_title',$row['title'].' · '.$brand)),'metaDescription'=>$desc,'canonicalUrl'=>\site_url('pages/'.$slug),'openGraphTitle'=>$row['seo_title']?:$row['title'],'openGraphDescription'=>$desc,'companyName'=>$brand,'publicPageAssets'=>true,'page'=>$row,'safeContent'=>$safe,'noindex'=>\auth_check()]);
    }
    public function robots():void
    {
        header('Content-Type: text/plain; charset=utf-8');header('X-Content-Type-Options: nosniff');$base=(string)config('SITE_URL');$host=(string)(parse_url($base,PHP_URL_HOST)??'');$robotsBase=(string)(parse_url($base,PHP_URL_PATH)??'');$robotsBase='/'.trim($robotsBase,'/');if($robotsBase==='/')$robotsBase='';if(!in_array(strtolower($host),['localhost','127.0.0.1'],true))echo "User-agent: *\nAllow: {$robotsBase}/\nDisallow: {$robotsBase}/admin/\nDisallow: {$robotsBase}/client/\nDisallow: {$robotsBase}/api/\nSitemap: ".\site_url('sitemap.xml')."\n";else echo "User-agent: *\nDisallow: /\n";
    }
    public function sitemap():void
    {
        header('Content-Type: application/xml; charset=utf-8');header('X-Content-Type-Options: nosniff');$urls=[['loc'=>\site_url(),'lastmod'=>date(DATE_ATOM)]];$static=['platform','accounts','company','about','security','terms','privacy','risk-disclosure','contact','faq','markets','education','articles','market-news'];foreach($static as $slug)$urls[]=['loc'=>\site_url($slug),'lastmod'=>date(DATE_ATOM)];foreach(['forex','metals','indices','commodities','stocks','digital-assets'] as $slug)$urls[]=['loc'=>\site_url('markets/'.$slug),'lastmod'=>date(DATE_ATOM)];$pages=Database::connection()->query("SELECT slug,updated_at FROM pages WHERE status='published' AND published_at<=CURRENT_TIMESTAMP AND slug NOT IN ('about','security','terms','privacy','risk-disclosure') ORDER BY slug")->fetchAll();foreach($pages as $p)$urls[]=['loc'=>\site_url('pages/'.$p['slug']),'lastmod'=>date(DATE_ATOM,strtotime($p['updated_at']))];$articles=Database::connection()->query("SELECT slug,updated_at FROM articles WHERE status='published' AND published_at<=CURRENT_TIMESTAMP ORDER BY published_at DESC")->fetchAll();foreach($articles as $a){$loc=\site_url('article/'.$a['slug']);$urls[]=['loc'=>$loc,'lastmod'=>date(DATE_ATOM,strtotime($a['updated_at']))];$urls[]=['loc'=>\site_url('articles/'.$a['slug']),'lastmod'=>date(DATE_ATOM,strtotime($a['updated_at']))];}echo '<?xml version="1.0" encoding="UTF-8"?>';echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($urls as $u)echo '<url><loc>'.htmlspecialchars($u['loc'],ENT_XML1|ENT_QUOTES,'UTF-8').'</loc><lastmod>'.$u['lastmod'].'</lastmod></url>';echo '</urlset>';
    }
    private function redirect(string $type,string $slug):void{$q=Database::connection()->prepare('SELECT target_slug FROM cms_slug_redirects WHERE entity_type=? AND old_slug=? LIMIT 1');$q->execute([$type,$slug]);$target=$q->fetchColumn();if(is_string($target)&&$target!==''){$path=$type==='article'?'article/':'pages/';\redirect($path.$target,301);}if($type==='page'){$q=Database::connection()->prepare('SELECT slug FROM pages WHERE slug=? AND status<>\'published\' LIMIT 1');$q->execute([$slug]);if($q->fetchColumn()){http_response_code(404);\render('public/not-found',['title'=>'Page not found']);return;}}http_response_code(404);\render('public/not-found',['title'=>'Page not found']);}
}
